HEAD = PatternFill('solid', fgColor='DDE6F2')
WRAP = Alignment(wrap_text=True, vertical='top')
BOLD = Font(bold=True)


def sheet(ws, head, rows, widths):
    ws.append(head)
    for c in ws[1]:
        c.font, c.fill, c.alignment = BOLD, HEAD, WRAP
    for r in rows:
        ws.append(list(r))
    for i, w in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = w
    for row in ws.iter_rows(min_row=2):
        for c in row:
            c.alignment = WRAP
    ws.freeze_panes = 'A2'
    ws.auto_filter.ref = ws.dimensions


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = 'Находки'
    sheet(ws, ['№', 'Раздел', 'Важность', 'Что не так', 'Где', 'Последствие', 'Предложение', 'Вопрос №'],
          [(i, *f) for i, f in enumerate(FIND, 1)], [5, 20, 11, 60, 34, 40, 44, 9])
    sheet(wb.create_sheet('Вопросы'), ['№', 'Тема', 'Вопрос'], QUEST, [5, 22, 110])
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    wb.save(OUT)
    print(OUT, '— находок', len(FIND), ', вопросов', len(QUEST))


if __name__ == '__main__':
    main()
